import React from 'react';

export default function Sidebar() {
  const menuItems = [
    { name: 'Dashboard', icon: '📊' },
    { name: 'Overview', icon: '👤' },
    { name: 'Students', icon: '👥' },
    { name: 'Teachers & Classes', icon: '📚' },
    { name: 'Reports', icon: '📑' },
    { name: 'Settings', icon: '⚙️' },
  ];

  return (
    <div style={{ width: '250px', backgroundColor: '#1e40af', color: '#fff', height: '100vh', padding: '20px' }}>
      <h2 style={{ marginBottom: '40px' }}>Libary</h2>
      {menuItems.map((item, i) => (
        <div key={i} style={{ padding: '15px 10px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '10px' }}>
          <span>{item.icon}</span> {item.name}
        </div>
      ))}
    </div>
  );
}
